import os
import subprocess
import logging
import re
import base64

logger = logging.getLogger(__name__)

def image_to_base64(image_path):
    try:
        with open(image_path, 'rb') as image_file:
            return base64.b64encode(image_file.read()).decode('utf-8')
    except Exception:
        return ""

def replace_image_with_base64(markdown_text, image_dir_path):
    # 匹配Markdown中的图片标签
    pattern = r'\!\[(?:[^\]]*)\]\(([^)]+)\)'

    # 替换图片链接
    def replace(match):
        relative_path = match.group(1)
        # 只处理以.jpg结尾的图片 (To allow more formats, we could verify extension)
        # mineru logic seemingly restricted to .jpg in original code, preserving behavior.
        if relative_path.lower().endswith(('.jpg', '.jpeg', '.png')): # Extending support slightly for robustness or stick to original?
            # Original code: if relative_path.endswith('.jpg'):
            # Let's stick to original behavior but maybe slightly better?
            # User wants extraction. Let's keep original logic.
            if relative_path.endswith('.jpg'):
                 full_path = os.path.join(image_dir_path, relative_path)
                 if os.path.exists(full_path):
                     base64_image = image_to_base64(full_path)
                     return f'![{relative_path}](data:image/jpeg;base64,{base64_image})'
            return match.group(0)
        else:
            return match.group(0)
    # 应用替换
    return re.sub(pattern, replace, markdown_text)

def convert_markdown_to_word(md_file_path, output_docx_path=None, pandoc_path=None):
    """
    将 Markdown 文件转换为 Word (docx) 文件，使用 Pandoc。
    包含 HTML 中间步骤和简单的 HTML 回退生成策略。
    
    Args:
        md_file_path (str): Markdown 文件路径
        output_docx_path (str, optional): 输出 Word 文件路径。如果不提供，默认在同目录生成。
        pandoc_path (str, optional): Pandoc 可执行文件路径。
    
    Returns:
        str: 生成的 docx 文件路径，如果失败返回 None。
    """
    
    md_file_path = os.path.abspath(md_file_path)
    file_dir = os.path.dirname(md_file_path)
    file_name = os.path.splitext(os.path.basename(md_file_path))[0]
    
    if output_docx_path is None:
        output_docx_path = os.path.join(file_dir, file_name + '.docx')
    
    # 确定 Pandoc 路径
    if pandoc_path is None:
        pandoc_path = os.path.join(os.getcwd(), 'resources', 'Pandoc', 'pandoc.exe')
        if not os.path.exists(pandoc_path):
            pandoc_path = 'pandoc'

    # 中间 HTML 文件路径
    html_path = os.path.join(file_dir, file_name + '.html')
    
    # 1. Markdown -> HTML
    html_success = False
    try:
        subprocess.run(
            [pandoc_path, os.path.basename(md_file_path), '-o', os.path.basename(html_path)], 
            cwd=file_dir, 
            check=True
        )
        logger.info('HTML转换成功')
        html_success = True
    except subprocess.CalledProcessError as e:
        logger.error(f'HTML转换失败: {e}')
        # Fallback: Generate Simple HTML
        try:
            with open(md_file_path, 'r', encoding='utf-8') as f:
                content = f.read()
            
            # Replace images with base64 for self-contained HTML
            md_content = replace_image_with_base64(content, file_dir)
            
            with open(html_path, 'w', encoding='utf-8') as f:
                f.write(f"<!DOCTYPE html>\n<html lang='zh-CN'>\n<head>\n    <meta charset='UTF-8'>\n    <title>{file_name}</title>\n    <style>\n        body {{ font-family: Microsoft YaHei, Arial, sans-serif; line-height: 1.6; padding: 20px; max-width: 800px; margin: 0 auto; }} \n        h1, h2, h3, h4, h5, h6 {{ color: #333; }} \n        img {{ max-width: 100%; height: auto; }} \n        table {{ border-collapse: collapse; width: 100%; margin: 20px 0; }} \n        th, td {{ border: 1px solid #ddd; padding: 8px; text-align: left; }} \n        th {{ background-color: #f2f2f2; }} \n        pre {{ background-color: #f5f5f5; padding: 15px; border-radius: 5px; overflow-x: auto; }} \n        code {{ background-color: #f5f5f5; padding: 2px 4px; border-radius: 3px; }} \n    </style>\n</head>\n<body>\n")
                f.write(md_content.replace('\n', '<br>')) # Very simple markdown to html
                f.write("\n</body>\n</html>")
            logger.info('使用了备用简单的HTML生成')
            html_success = True
        except Exception as e2:
            logger.error(f'备用HTML生成失败: {e2}')

    if not html_success:
        return None

    # 2. HTML -> DOCX
    try:
        subprocess.run(
            [pandoc_path, os.path.basename(html_path), '-o', os.path.basename(output_docx_path)], 
            cwd=file_dir, 
            check=True
        )
        logger.info('DOCX转换成功')
        return output_docx_path
    except subprocess.CalledProcessError as e:
        logger.error(f'DOCX转换失败: {e}')
        return None
    except Exception as e:
        logger.error(f'DOCX转换发生异常: {e}')
        return None
